  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopbop.com/ci/v2/shopbop_affiliate_program.html?ref_=SB_D_GBP_FTR_SB_AFL', 'official_site', 'ugc_collab', 'Shopbop''s official affiliate page runs a Campus Ambassador program: undergraduates apply by emailing shopbopcampus@amazon.com with their Instagram/TikTok handles, post at least 3 Shopbop affiliate links per month through ShopMy, and can earn a 15% commission rate on qualifying affiliate purchases.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopbop.com/ci/v2/influencerprogramterms.html', 'official_site', 'affiliate', 'Shopbop''s official Influencer Program Terms (updated October 29, 2026) state commissions are earned through third-party affiliates Rakuten, LTK, ShopMy and Split, that Shopbop sets the rates paid to those affiliates, and that enrollment is by application with approval at Shopbop''s discretion.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/shopbop/', 'affiliate_network', 'compensation', 'LinkClicky lists Shopbop''s general affiliate program on Rakuten Advertising at 1% per sale (updated March 11, 2024); the 15% figure on Shopbop''s own page applies only to the student Campus Ambassador route via ShopMy.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 6, 11, 8, 5, '{"niche_fit": "Designer and contemporary women''s fashion is a core creator category, and Shopbop is a long-standing influencer-shopping destination.", "ugc_evidence": "Two official creator structures: an Influencer Program built on LTK/ShopMy-style linking and a Campus Ambassador program requiring monthly Instagram/TikTok content.", "compensation": "The general Rakuten program is listed at just 1% per sale; the official 15% rate is limited to undergraduate Campus Ambassadors via ShopMy. No cap statement was found.", "contact_access": "A published creator application email (shopbopcampus@amazon.com) plus the official influencer program enrollment route.", "opportunity_availability": "Influencer Program enrollment is open by application; the higher-rate campus route is restricted to undergraduate students.", "credibility": "Established retailer owned by Amazon, operating since 2000."}'::jsonb);
