  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.trip.com/partners/index?locale=zh-TW&curr=IDR', 'official_site', 'affiliate', 'Trip.com''s official affiliate program page headlines ''up to 7% commission'' (7% stated as the maximum basic commission), a 30-day website cookie, and 20,000+ existing affiliate partners; its FAQ says everyone can apply, no website is required, and there is no cost to join. No earnings-cap statement appears.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliates-directory.com/websites/trip-com', 'listing', 'compensation', 'Affiliates-Directory''s breakdown of the Trip.com offer via Travelpayouts gives category rates: hotels up to 5.5%, international flights 1%, trains 1.8%, car rentals and transfers up to 4.5%, attractions about 1.36% - product-based, one-time commissions paid after travel completes.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliateprogramsguru.com/programs/trip-com-affiliate-program/', 'listing', 'compensation', 'AffiliateProgramsGuru describes the Trip.com program running through Awin with hotels up to 6%, flights up to 3% and attractions up to 8%, which conflicts with both the official ''up to 7%'' headline and the Travelpayouts category table, so no single rate is recorded.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 12, 9, 8, 9, 5, '{"niche_fit": "A full-service OTA covering hotels, flights, trains and attractions in one program - a core monetization route for travel creators.", "ugc_evidence": "The program explicitly welcomes bloggers and individual creators and reports 20,000+ affiliate partners, though it is publisher-led rather than a structured creator program.", "compensation": "The official page publishes only an ''up to 7%'' ceiling and category rates conflict across channels (hotels 5.5% vs 6%; attractions 1.36% vs 8%), so no rate is recorded and no cap statement was found.", "contact_access": "Direct partner signup on Trip.com''s own partners page; no published partnerships email.", "opportunity_availability": "Open to everyone including individuals without a website, per the official FAQ.", "credibility": "Trip.com Group is one of the world''s largest travel companies, listed on Nasdaq and the Hong Kong Stock Exchange."}'::jsonb);
