  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 11, 8, 6, 7, 5, '{"niche_fit": "A major US OTA whose hotel and flight deals are a staple of budget-travel content.", "ugc_evidence": "A long-running affiliate program accepting blogs and influencer channels, but no structured creator or ambassador program.", "compensation": "Published ranges conflict (3-5% per Lasso; 3-7% per UpPromote and Empire Flippers), so no rate is recorded and no cap statement was found.", "contact_access": "Access is via network application (CJ Affiliate; one directory also names Rakuten); no published partnerships email.", "opportunity_availability": "Open application through the network with manual review; Lasso notes a live site or app with original travel content is required.", "credibility": "Part of Booking Holdings, the world''s largest online travel group."}'::jsonb);
