  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 11, 7, 8, 4, '{"niche_fit": "Intercity bus travel is a narrower niche than flights or hotels, but Busbud is the category''s global booking leader and fits budget and overland travel content.", "ugc_evidence": "An open partner program marketed to content and travel sites with banners, links and a support team; no dedicated creator program.", "compensation": "Travelpayouts publishes 5% of each order for its channel; a separate CJ channel is listed at 2% and is documented. No cap statement was found.", "contact_access": "Joining runs through the Travelpayouts network; no published Busbud partnerships email was found.", "opportunity_availability": "Partnership program open to partners worldwide through Travelpayouts.", "credibility": "Operating since 2011 with nearly 4,000 bus-company partners across 80+ countries."}'::jsonb);
