  insert into public.brands (name, website, description, country, status) values ('Prime Bites', 'https://primebites.com', 'Protein snack brand from Alpha Prime selling soft-baked protein brownies (19g protein, 5g collagen per brownie), mini muffins and rice treats baked in its Miami bakery. It bills itself as the #1 Food & Snack brand on TikTok Shop with 20,000,000 brownies sold, and is also stocked at Target, Walmart, Costco and BJ''s.', 'United States', 'published') returning id into bid;
