  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 19, 12, 7, 9, 5, '{"compensation": "Published 10% public commission rate on TikTok Shop offers; no cap statement found, so cap is honestly unknown.", "contact_access": "No published creator email or application page found; the route in is the TikTok Shop affiliate program itself.", "credibility": "20M+ brownies sold and national retail distribution at Target, Walmart, Costco and BJ''s.", "niche_fit": "Protein dessert snacks built for TikTok food content \u2014 a top-selling TikTok Shop food brand with highly demonstrable, taste-test-friendly products.", "opportunity_availability": "Products are openly listed for TikTok Shop affiliates at a public rate, so any eligible creator can promote them.", "ugc_evidence": "The brand''s growth is TikTok Shop creator-driven; marketplace listings show hundreds of thousands of reported sales through creator-sold offers."}'::jsonb);
