  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'G FUEL Affiliate / Ambassador Program', 'https://gfuel.com/en-ca/pages/community', 'https://gfuel.com/en-ca/pages/community', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gfuel.com/en-ca/pages/community', 'official_site', 'affiliate_terms', 'G Fuel''s official Ambassador page invites content creators to apply: affiliates receive a personal code giving fans 20% off at GFUEL.com and earn commission on every sale, paid via PayPal, plus free product, merch and early flavor access. Applicants must be 18+. Program questions go to ambassadors@gfuel.com. The page confirms commission is paid but does not publish the percentage.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theaffiliatemonkey.com/affiliate/g-fuel-affiliate-program/', 'listing', 'affiliate', 'The Affiliate Monkey''s program review states the G Fuel affiliate program is managed through the GoAffPro platform and pays a 10% commission on qualified transactions, paid monthly via PayPal. The brand''s own page does not publish the rate, so 10% is recorded as publicly reported.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://goaffpro.com/case-study/gfuel', 'affiliate_network', 'general', 'GoAffPro''s own case study confirms G Fuel runs its affiliate program on GoAffPro (portal at affiliates.gfuel.com) with 1100+ affiliates generating eight figures in referral revenue. An affiliate count above 1,100 is far above the ~100-creator scale required for a ''low'' saturation mark, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 18, 11, 13, 8, 5, '{"compensation": "10% commission publicly reported by program reviews plus free product and merch; no cap statement found, so cap is unknown.", "contact_access": "Public application form on the official page plus a published program email (ambassadors@gfuel.com) \u2014 top band.", "credibility": "Founded 2012, category-defining gaming energy brand with national retail presence and eight figures of affiliate-driven revenue.", "niche_fit": "Energy drinks are a staple creator category; G Fuel is gaming/streamer-skewed rather than general wellness, which trims the fit slightly.", "opportunity_availability": "Applications are publicly open on the official site to creators 18+.", "ugc_evidence": "A dedicated ambassador program built for content creators, with 1100+ affiliates per the platform''s own case study."}'::jsonb);
