  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.crossrope.com/pages/partner-lp-affiliates', 'official_site', 'ugc_collab', 'Crossrope''s own partner page (fetched) is a creator partnership hub: brand guide, demo videos, B-roll and photo collections for partners, video content tips (transformations, unboxings, tutorials), and an iDev-based partner account where partners earn commission on purchases within 30 days of a click; partners submit W-9/W-8BEN forms to ap@crossrope.com for payment setup.', 'verified', now());
