  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 7, 12, 6, 4, '{"niche_fit": "Dog GPS and activity tracking is highly demonstrable pet-tech content for dog creators.", "ugc_evidence": "The brand publicly recruited UGC reps on Instagram with gifted product and a commission scheme, beyond its standard Awin programme.", "compensation": "Awin publishes only an ''up to 10%'' ceiling with no base rate, so no rate is recorded.", "contact_access": "A published affiliate contact email (affiliates@pitpatpet.com) on the Awin profile, plus full programme terms on the brand''s own site.", "opportunity_availability": "Open on Awin but restricted to UK sign-ups only.", "credibility": "Established UK pet-tech company (Pitpatpet Ltd, Cambridge) with 37K Instagram followers."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('PetLink', 'https://www.petlink.net', 'Pet safety brand with 30+ years in pet identification, selling microchips, QR tags and the PetLinkGPS dog tracker and activity monitor (live location, geofence alerts, activity tracking) through its online store.', 'United States', 'published') returning id into bid;
