  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/111234', 'affiliate_network', 'affiliate', 'PetLink''s Awin (US) merchant profile (fetched) publishes a ''20% Standard Commission'' (5% for coupon/discount sites) calculated on the final transaction amount excluding VAT and shipping, a 30-day cookie, and an average order value of $99.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/111234', 'affiliate_network', 'general', 'The profile states PetLink has been in pet safety for over 30 years, launched its GPS product in 2024, is growing its direct-to-consumer offering with ''growing volumes of sales each month'', and offers a reactive account manager and private commission rates for valuable exposure.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/111234', 'affiliate_network', 'compensation', 'No earnings-cap statement appears in the Awin profile, so the commission cap is recorded as unknown; the GPS line''s 2024 launch is noted but is not, by itself, evidence of low creator saturation.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 8, 16, 8, 9, 4, '{"niche_fit": "GPS pet tracking (lost-dog recovery, geofence alerts, activity) is demonstrable, story-driven pet content.", "ugc_evidence": "No creator or ambassador program evidence found \u2014 a standard network affiliate program, though the brand invites tailored partnership proposals.", "compensation": "A strong published 20% standard commission on Awin with a $99 average order value and 30-day cookie.", "contact_access": "Awin application route; the profile offers a reactive account manager and invites private-rate proposals, but no public email is published.", "opportunity_availability": "Open on Awin (US) with the brand actively pushing direct-to-consumer growth since the 2024 GPS launch.", "credibility": "Pet-identification brand claiming 30+ years in pet safety, now expanding into GPS trackers."}'::jsonb);
